use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,io::Write};
use zopro_bn254::{Fq,Fq2,Fr,G2Affine};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){let a=std::env::args().collect::<Vec<_>>();assert_eq!(a.len(),5);assert!(!std::path::Path::new(&a[4]).exists());
let bytes=fs::read(&a[1]).unwrap();let oracle:Value=serde_json::from_slice(&fs::read(&a[2]).unwrap()).unwrap();let trace:Value=serde_json::from_slice(&fs::read(&a[3]).unwrap()).unwrap();let fixture=sha(&bytes);assert_eq!(fixture,oracle["fixture_sha256"]);assert_eq!(fixture,trace["fixture_sha256"]);assert_eq!(oracle["independent_Arkworks_complete_MSM"],true);assert_eq!(&bytes[..8],b"B2SCAN01");let n=u64::from_le_bytes(bytes[8..16].try_into().unwrap())as usize;assert_eq!(bytes.len(),16+160*n);
let points=bytes[16..16+128*n].chunks_exact(128).map(|p|{let f=p.chunks_exact(32).map(|v|Fq::from_be_bytes(v.try_into().unwrap()).unwrap()).collect::<Vec<_>>();let p=G2Affine::new(Fq2::new(f[1],f[0]),Fq2::new(f[3],f[2]));assert!(p.is_on_curve());p}).collect::<Vec<_>>();let words=bytes[16+128*n..].chunks_exact(32).map(|v|{let w=std::array::from_fn(|i|u64::from_le_bytes(v[8*i..8*i+8].try_into().unwrap()));assert!(Fr::from_canonical(w).is_some());w}).collect::<Vec<_>>();drop(bytes);
let(root,scalars,grouped)=zopro_core::codec_root(&points,&words);assert_eq!(root.len(),scalars.len());assert!(trace["rows"].as_array().unwrap().iter().all(|r|r["root_points"]==root.len()));
let fields=scalars.iter().map(|w|Fr::from_canonical(*w).unwrap()).collect::<Vec<_>>();let result=zopro_core::msm_g2(&root,&fields).to_affine();let mut h=Sha256::new();for f in[result.x.c0,result.x.c1,result.y.c0,result.y.c1]{for w in f.to_canonical(){h.update(w.to_le_bytes());}}let actual=format!("{:x}",h.finalize());assert_eq!(actual,oracle["expected_canonical_result_sha256"]);
let mut totals=[Fq::ZERO;8];let mut groups=0;for row in trace["rows"].as_array().unwrap(){let lo=row["start"].as_u64().unwrap()as usize;let hi=row["end"].as_u64().unwrap()as usize;for component in row["batches"].as_array().unwrap(){for batch in component.as_array().unwrap(){for group in batch.as_array().unwrap().chunks_exact(8){groups+=1;for(lane,i)in group.iter().enumerate(){let i=i.as_u64().unwrap()as usize;assert!(lo<=i&&i<hi);let p=root[i];totals[lane]+=p.x.c0.square()+p.x.c1.square()+p.y.c0.square()+p.y.c1.square();}}}}}
let mut file=fs::OpenOptions::new().write(true).create_new(true).open(&a[4]).unwrap();file.write_all(b"B2ROOT01").unwrap();file.write_all(&(root.len()as u64).to_le_bytes()).unwrap();let mut raw_hash=Sha256::new();for p in&root{assert!(p.is_on_curve());for f in[p.x.c0,p.x.c1,p.y.c0,p.y.c1]{for w in f.0{let b=w.to_le_bytes();file.write_all(&b).unwrap();raw_hash.update(b);}}}file.sync_all().unwrap();drop(file);
let mut meta=json!({"fixture_sha256":fixture,"trace_sha256":sha(&fs::read(&a[3]).unwrap()),"original_points":n,"root_points":root.len(),"full_groups":groups,"grouped":grouped,"accepted_scalar_groups_and_group_affine":true,"complete_MSM_matches_pinned_independent_Arkworks_oracle":true,"result_sha256":actual,"raw_root_sha256":format!("{:x}",raw_hash.finalize()),"file_sha256":sha(&fs::read(&a[4]).unwrap()),"payload_bytes":root.len()*128,"private_path":a[4],"new_proofs":0,"timed":false});let mut private=meta.clone();private["scalar_norm_sum_raw_words"]=json!(totals.map(|f|f.0));let path=format!("{}.json",a[4]);assert!(!std::path::Path::new(&path).exists());fs::write(&path,serde_json::to_vec_pretty(&private).unwrap()).unwrap();meta["private_expected_metadata_sha256"]=json!(sha(&fs::read(&path).unwrap()));println!("ROOT {meta}");}
